<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?></title><link rel="stylesheet" href="<?= base_url('assets/bootstrap.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/management.css') ?>"><style>body{background:linear-gradient(135deg,#f8f4ff,#eee3ff);min-height:100vh}.auth-nav{display:flex;justify-content:space-between;padding:25px 6%;background:white}.auth-nav a{font-size:24px;font-weight:800}.auth-nav small{font-weight:400;color:#9a86b1}.auth-card{background:white;border:1px solid #e9ddf7;border-radius:18px;box-shadow:0 20px 80px #49227412;width:calc(100% - 30px);max-width:520px;margin:55px auto;padding:38px}.auth-card h1{margin:14px 0 25px}.auth-card .form-control{margin-bottom:15px}.auth-card .alert{font-size:13px}.auth-bottom{text-align:center;margin:22px 0 0}.auth-mark{text-align:center;color:#7428dc;font-size:22px;font-weight:800}.form-label{display:block}@media(max-width:540px){.auth-card{padding:24px;margin:25px auto}}</style></head><body><nav class="auth-nav"><a href="<?= site_url() ?>">ShopEase <small>Online Store</small></a></nav><main class="auth-card"><div class="auth-mark">ShopEase</div><?php foreach(['success','error','access_error'] as $type): ?><?php if($message=session()->getFlashdata($type)): ?><div class="alert alert-<?= $type==='success'?'success':'danger' ?>" role="status"><?= esc($message) ?></div><?php endif ?><?php endforeach ?><?php if(!empty($error)): ?><div class="alert alert-danger" role="alert"><?= esc($error) ?></div><?php endif ?><?php if(!empty($errors)): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach($errors as $message): ?><li><?= esc($message) ?></li><?php endforeach ?></ul></div><?php endif ?><?= $this->renderSection('content') ?></main></body></html>